# no las agrega a una base vieja, así que se agregan acá.
COLUMNAS_NUEVAS_CLASES = {
    'serie_id': 'INTEGER REFERENCES series(id)',
    'estado': "TEXT NOT NULL DEFAULT 'programada'",
}


def inicializar():
    with conexion() as con:
        con.executescript(ESQUEMA)
        existentes = {f['name'] for f in con.execute('PRAGMA table_info(clases)').fetchall()}
        for columna, definicion in COLUMNAS_NUEVAS_CLASES.items():
            if columna not in existentes:
                con.execute(f'ALTER TABLE clases ADD COLUMN {columna} {definicion}')

