class NuevaSerie(BaseModel):
    nombre: Texto
    instructor: Texto
    dia: str
    hora: HoraTexto
    duracion_min: int = Field(ge=1)
    cupo: int = Field(ge=1)
    desde: date
    hasta: date

    @field_validator('dia')
    @classmethod
    def dia_valido(cls, dia):
        if dia not in DIAS:
            raise ValueError('día inválido')
        return dia

    @model_validator(mode='after')
    def fechas_validas(self):
        if self.hasta < self.desde:
            raise ValueError('hasta es anterior a desde')
        if (self.hasta - self.desde).days > MAX_DIAS_SERIE:
            raise ValueError(f'la serie no puede abarcar más de {MAX_DIAS_SERIE} días')
        return self


class CambioSerie(BaseModel):
    desde_clase_id: int
    hora: HoraTexto | None = None
    instructor: Texto | None = None
    cupo: int | None = Field(default=None, ge=1)

    @model_validator(mode='before')
    @classmethod
    def sin_nulos(cls, datos):
        if isinstance(datos, dict):
            for campo in ('hora', 'instructor', 'cupo'):
                if campo in datos and datos[campo] is None:
                    raise ValueError(f'{campo} no puede ser null')
        return datos

    @model_validator(mode='after')
    def hay_cambios(self):
        if self.hora is None and self.instructor is None and self.cupo is None:
            raise ValueError('no viene ningún cambio')
        return self


def ver_serie(serie):
    return dict(serie, clases=[ver_clase(c) for c in db.clases_de_serie(serie['id'])])


@router.post('/admin/series', status_code=201, dependencies=[Depends(admin)])
def crear_serie(datos: NuevaSerie):
    inicios = inicios_de_serie(datos.dia, datos.hora, datos.desde, datos.hasta, reloj.ahora())
    serie_id = db.crear_serie(datos.nombre, datos.instructor, datos.dia, datos.hora, datos.duracion_min,
                              datos.cupo, datos.desde.isoformat(), datos.hasta.isoformat(), inicios)
    return ver_serie(db.serie(serie_id))


@router.get('/admin/series/{serie_id}', dependencies=[Depends(admin)])
def obtener_serie(serie_id: int):
    serie = db.serie(serie_id)
    if serie is None:
        raise HTTPException(404, 'No existe la serie')
    return ver_serie(serie)


@router.patch('/admin/series/{serie_id}', dependencies=[Depends(admin)])
def cambiar_serie(serie_id: int, datos: CambioSerie):
    serie = db.serie(serie_id)
    if serie is None:
        raise HTTPException(404, 'No existe la serie')
    desde = db.clase(datos.desde_clase_id)
    if desde is None or desde['serie_id'] != serie_id:
        raise HTTPException(404, 'La clase no es de esta serie')
    ahora = reloj.ahora()
    inicio_desde = db.a_fecha(desde['inicio'])
    if inicio_desde <= ahora:
        raise HTTPException(409, 'La clase ya empezó')

    # Se calcula todo antes de escribir: si una clase no cumple, no cambia ninguna.
    cambios = []
    for clase in db.clases_de_serie(serie_id):
        if clase['estado'] != 'programada':
            continue
        inicio = db.a_fecha(clase['inicio'])
        if clase['id'] != desde['id'] and inicio <= inicio_desde:
            continue
        nuevo_inicio = inicio if datos.hora is None else con_hora(inicio, datos.hora)
        if nuevo_inicio <= ahora:
            raise HTTPException(409, 'Con la hora nueva, una clase ya habría empezado')
        if datos.cupo is not None and db.confirmadas(clase['id']) > datos.cupo:
            raise HTTPException(409, 'Con el cupo nuevo, una clase tendría más reservas que lugares')
        instructor = clase['instructor'] if datos.instructor is None else datos.instructor
        cupo = clase['cupo'] if datos.cupo is None else datos.cupo
        cambios.append((clase, nuevo_inicio, instructor, cupo))

    hora = serie['hora'] if datos.hora is None else datos.hora
    instructor = serie['instructor'] if datos.instructor is None else datos.instructor
    cupo = serie['cupo'] if datos.cupo is None else datos.cupo
    db.aplicar_cambio_serie(serie_id, hora, instructor, cupo,
                            [(c['id'], inicio, instr, cup) for c, inicio, instr, cup in cambios])

    for clase, nuevo_inicio, _, _ in cambios:
        if nuevo_inicio == db.a_fecha(clase['inicio']):
            continue
        for socio in db.socios_confirmados(clase['id']):
            correo.enviar(socio['email'],
                          f"Cambio de horario: {clase['nombre']} el {correo.fecha_y_hora(nuevo_inicio)}",
                          f"Hola {socio['nombre']}, {clase['nombre']} cambió de horario: ahora es el "
                          f"{correo.fecha_y_hora(nuevo_inicio)}.")
    return ver_serie(db.serie(serie_id))


@router.post('/admin/clases/{clase_id}/cancelar', dependencies=[Depends(admin)])
def cancelar_una_clase(clase_id: int):
    clase = db.clase(clase_id)
    if clase is None:
        raise HTTPException(404, 'No existe la clase')
    if clase['estado'] == 'cancelada':
        raise HTTPException(409, 'La clase ya está cancelada')
    inicio = db.a_fecha(clase['inicio'])
    if inicio <= reloj.ahora():
