        correo.enviar(socio['email'], f"Clase cancelada: {clase['nombre']} el {correo.fecha_y_hora(inicio)}",
                      f"Hola {socio['nombre']}, se canceló {clase['nombre']} y te devolvimos el crédito.")
    return ver_clase(db.clase(clase_id))


