class NuevaSerie(BaseModel):
    nombre: Texto
    instructor: Texto
    dia: str
    hora: HoraTexto
    duracion_min: int = Field(ge=1)
    cupo: int = Field(ge=1)
    desde: date
    hasta: date

    @field_validator('dia')
    @classmethod
    def dia_valido(cls, dia):
        if dia not in DIAS:
            raise ValueError('día inválido')
        return dia

    @model_validator(mode='after')
    def fechas_validas(self):
        if self.hasta < self.desde:
            raise ValueError('hasta es anterior a desde')
        if (self.hasta - self.desde).days > MAX_DIAS_SERIE:
            raise ValueError(f'la serie no puede abarcar más de {MAX_DIAS_SERIE} días')
        return self


class CambioSerie(BaseModel):
    desde_clase_id: int
    hora: HoraTexto | None = None
    instructor: Texto | None = None
    cupo: int | None = Field(default=None, ge=1)

    @model_validator(mode='before')
    @classmethod
    def sin_nulos(cls, datos):
        if isinstance(datos, dict):
            for campo in ('hora', 'instructor', 'cupo'):
                if campo in datos and datos[campo] is None:
                    raise ValueError(f'{campo} no puede ser null')
        return datos

    @model_validator(mode='after')
    def hay_cambios(self):
        if self.hora is None and self.instructor is None and self.cupo is None:
            raise ValueError('no viene ningún cambio')
        return self


def ver_serie(serie):
    return dict(serie, clases=[ver_clase(c) for c in db.clases_de_serie(serie['id'])])


@router.post('/admin/series', status_code=201, dependencies=[Depends(admin)])
def crear_serie(datos: NuevaSerie):
    inicios = inicios_de_serie(datos.dia, datos.hora, datos.desde, datos.hasta, reloj.ahora())
    serie_id = db.crear_serie(datos.nombre, datos.instructor, datos.dia, datos.hora, datos.duracion_min,
                              datos.cupo, datos.desde.isoformat(), datos.hasta.isoformat(), inicios)
    return ver_serie(db.serie(serie_id))


