    if serie is None:
        raise HTTPException(404, 'No existe la serie')
    return ver_serie(serie)


@router.patch('/admin/series/{serie_id}', dependencies=[Depends(admin)])
def cambiar_serie(serie_id: int, datos: CambioSerie):
    serie = db.serie(serie_id)
    if serie is None:
        raise HTTPException(404, 'No existe la serie')
    desde = db.clase(datos.desde_clase_id)
    if desde is None or desde['serie_id'] != serie_id:
        raise HTTPException(404, 'La clase no es de esta serie')
    ahora = reloj.ahora()
    inicio_desde = db.a_fecha(desde['inicio'])
    if inicio_desde <= ahora:
        raise HTTPException(409, 'La clase ya empezó')

    # Se calcula todo antes de escribir: si una clase no cumple, no cambia ninguna.
    cambios = []
    for clase in db.clases_de_serie(serie_id):
        if clase['estado'] != 'programada':
            continue
        inicio = db.a_fecha(clase['inicio'])
        if clase['id'] != desde['id'] and inicio <= inicio_desde:
            continue
        nuevo_inicio = inicio if datos.hora is None else con_hora(inicio, datos.hora)
        if nuevo_inicio <= ahora:
            raise HTTPException(409, 'Con la hora nueva, una clase ya habría empezado')
        if datos.cupo is not None and db.confirmadas(clase['id']) > datos.cupo:
            raise HTTPException(409, 'Con el cupo nuevo, una clase tendría más reservas que lugares')
        instructor = clase['instructor'] if datos.instructor is None else datos.instructor
        cupo = clase['cupo'] if datos.cupo is None else datos.cupo
        cambios.append((clase, nuevo_inicio, instructor, cupo))

    hora = serie['hora'] if datos.hora is None else datos.hora
    instructor = serie['instructor'] if datos.instructor is None else datos.instructor
    cupo = serie['cupo'] if datos.cupo is None else datos.cupo
    db.aplicar_cambio_serie(serie_id, hora, instructor, cupo,
                            [(c['id'], inicio, instr, cup) for c, inicio, instr, cup in cambios])

    for clase, nuevo_inicio, _, _ in cambios:
        if nuevo_inicio == db.a_fecha(clase['inicio']):
            continue
        for socio in db.socios_confirmados(clase['id']):
            correo.enviar(socio['email'],
                          f"Cambio de horario: {clase['nombre']} el {correo.fecha_y_hora(nuevo_inicio)}",
                          f"Hola {socio['nombre']}, {clase['nombre']} cambió de horario: ahora es el "
                          f"{correo.fecha_y_hora(nuevo_inicio)}.")
    return ver_serie(db.serie(serie_id))


